-- Mobilisation radar: vessels, geofences, fused signals, watchlist, alerts.
--
-- Contractors and operators are existing employers rows. Signals store the
-- employer id when a name resolves, and always store the watchlist row so
-- fusion still works before that link is confirmed. AIS positions are for
-- internal display and alerting only — commercial AIS licences prohibit
-- redistribution, so this table is not exposed to anon and rows older than
-- the poller's retention window are deleted.

CREATE TABLE IF NOT EXISTS "public"."vessels" (
  "vessel_id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "imo" character varying(7),
  "mmsi" character varying(9),
  "name" character varying(200) NOT NULL,
  "vessel_type" character varying(30) NOT NULL DEFAULT 'other',
  "owner_name" character varying(200) NOT NULL,
  "owner_operator_id" integer,
  "relevance" character varying(20) NOT NULL DEFAULT 'nw',
  "notes" text,
  "is_active" boolean NOT NULL DEFAULT true,
  "resolution_note" text,
  "last_lat" numeric(9,6),
  "last_lng" numeric(9,6),
  "last_sog_kn" numeric(6,2),
  "last_cog_deg" numeric(6,2),
  "last_destination" text,
  "last_eta" timestamp with time zone,
  "last_position_at" timestamp with time zone,
  "last_position_source" text,
  "inside_geofence_ids" integer[] NOT NULL DEFAULT '{}',
  "next_poll_at" timestamp with time zone,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "vessels_imo_unique" UNIQUE ("imo"),
  CONSTRAINT "vessels_name_owner_unique" UNIQUE ("name", "owner_name"),
  CONSTRAINT "vessels_type_check" CHECK (
    "vessel_type" IN (
      'pipelay', 'heavy_lift', 'dsv', 'survey', 'usv',
      'rock_install', 'dredger', 'fpso', 'construction', 'other'
    )
  ),
  CONSTRAINT "vessels_relevance_check" CHECK ("relevance" IN ('nw', 'global', 'low')),
  CONSTRAINT "vessels_imo_format_check" CHECK ("imo" IS NULL OR "imo" ~ '^[0-9]{7}$'),
  CONSTRAINT "vessels_owner_operator_id_fkey"
    FOREIGN KEY ("owner_operator_id") REFERENCES "public"."employers"("employer_id") ON DELETE SET NULL
);

COMMENT ON TABLE "public"."vessels" IS
  'Marine and subsea vessels on the mobilisation watch. IMO is the stable key; MMSI can change with flag.';

CREATE TABLE IF NOT EXISTS "public"."geofences" (
  "geofence_id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" character varying(200) NOT NULL,
  "slug" character varying(80) NOT NULL,
  "description" text,
  "geometry" jsonb NOT NULL,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_by" uuid,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "geofences_slug_unique" UNIQUE ("slug"),
  CONSTRAINT "geofences_geometry_type_check" CHECK (
    ("geometry"->>'type') IN ('Polygon', 'MultiPolygon')
  )
);

COMMENT ON TABLE "public"."geofences" IS
  'Editable region polygons. Seeded rings cover the NW Shelf, Browse and Bonaparte / Timor Sea and exclude Bass Strait.';

CREATE TABLE IF NOT EXISTS "public"."mobilisation_watch_contractors" (
  "watch_id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "canonical_name" character varying(200) NOT NULL,
  "aliases" text[] NOT NULL DEFAULT '{}',
  "employer_id" integer,
  "asx_ticker" character varying(12),
  "tier" character varying(20) NOT NULL DEFAULT 'core',
  "is_active" boolean NOT NULL DEFAULT true,
  "notes" text,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "mobilisation_watch_contractors_name_unique" UNIQUE ("canonical_name"),
  CONSTRAINT "mobilisation_watch_contractors_tier_check" CHECK ("tier" IN ('core', 'adjacent')),
  CONSTRAINT "mobilisation_watch_contractors_employer_id_fkey"
    FOREIGN KEY ("employer_id") REFERENCES "public"."employers"("employer_id") ON DELETE SET NULL
);

CREATE TABLE IF NOT EXISTS "public"."mobilisation_watch_vessels" (
  "watch_vessel_id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "vessel_id" integer NOT NULL,
  "is_active" boolean NOT NULL DEFAULT true,
  "notes" text,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "mobilisation_watch_vessels_vessel_unique" UNIQUE ("vessel_id"),
  CONSTRAINT "mobilisation_watch_vessels_vessel_id_fkey"
    FOREIGN KEY ("vessel_id") REFERENCES "public"."vessels"("vessel_id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "public"."mobilisation_watch_keywords" (
  "keyword_id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "keyword" character varying(200) NOT NULL,
  "kind" character varying(20) NOT NULL,
  "asx_ticker" character varying(12),
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "mobilisation_watch_keywords_unique" UNIQUE ("keyword", "kind"),
  CONSTRAINT "mobilisation_watch_keywords_kind_check" CHECK (
    "kind" IN ('region', 'operator', 'project', 'general')
  )
);

CREATE TABLE IF NOT EXISTS "public"."mobilisation_sources" (
  "source_key" text PRIMARY KEY,
  "layer" text NOT NULL,
  "display_name" text NOT NULL,
  "poll_interval_minutes" integer NOT NULL,
  "enabled" boolean NOT NULL DEFAULT true,
  "config" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "cursor" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "last_polled_at" timestamp with time zone,
  "last_success_at" timestamp with time zone,
  "last_error" text,
  CONSTRAINT "mobilisation_sources_layer_check" CHECK ("layer" IN ('regulatory', 'commercial', 'ais')),
  CONSTRAINT "mobilisation_sources_interval_check" CHECK ("poll_interval_minutes" BETWEEN 5 AND 10080)
);

CREATE TABLE IF NOT EXISTS "public"."mobilisation_rules" (
  "rule_id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" text NOT NULL,
  "name" text NOT NULL,
  "description" text,
  "enabled" boolean NOT NULL DEFAULT true,
  "priority" text NOT NULL,
  "config" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "mobilisation_rules_code_unique" UNIQUE ("code"),
  CONSTRAINT "mobilisation_rules_priority_check" CHECK ("priority" IN ('low', 'normal', 'high', 'critical'))
);

CREATE TABLE IF NOT EXISTS "public"."mobilisation_signals" (
  "signal_id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "source_layer" text NOT NULL,
  "source" text NOT NULL,
  "source_key" text,
  "signal_type" text NOT NULL,
  "occurred_at" timestamp with time zone NOT NULL,
  "detected_at" timestamp with time zone NOT NULL DEFAULT now(),
  "title" text NOT NULL,
  "extract" text,
  "url" text,
  "confidence" numeric(4,3) NOT NULL,
  "in_region" boolean NOT NULL DEFAULT true,
  "vessel_id" integer,
  "contractor_id" integer,
  "watch_contractor_id" integer,
  "operator_id" integer,
  "worksite_id" integer,
  "geofence_id" integer,
  "sector_id" integer,
  "region_label" text,
  "dedup_key" text NOT NULL,
  "fingerprint" text NOT NULL,
  "external_id" text,
  "matched_terms" text[] NOT NULL DEFAULT '{}',
  "also_seen" jsonb NOT NULL DEFAULT '[]'::jsonb,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "mobilisation_signals_dedup_unique" UNIQUE ("dedup_key"),
  CONSTRAINT "mobilisation_signals_fingerprint_unique" UNIQUE ("fingerprint"),
  CONSTRAINT "mobilisation_signals_layer_check" CHECK ("source_layer" IN ('regulatory', 'commercial', 'ais')),
  CONSTRAINT "mobilisation_signals_type_check" CHECK (
    "signal_type" IN (
      'ep_lodged', 'ep_varied', 'ep_accepted', 'activity_notification', 'enforcement',
      'award', 'news', 'vessel_area_entry', 'vessel_area_exit', 'vessel_course_toward'
    )
  ),
  CONSTRAINT "mobilisation_signals_confidence_check" CHECK ("confidence" >= 0 AND "confidence" <= 1),
  CONSTRAINT "mobilisation_signals_vessel_id_fkey"
    FOREIGN KEY ("vessel_id") REFERENCES "public"."vessels"("vessel_id") ON DELETE SET NULL,
  CONSTRAINT "mobilisation_signals_contractor_id_fkey"
    FOREIGN KEY ("contractor_id") REFERENCES "public"."employers"("employer_id") ON DELETE SET NULL,
  CONSTRAINT "mobilisation_signals_watch_contractor_id_fkey"
    FOREIGN KEY ("watch_contractor_id") REFERENCES "public"."mobilisation_watch_contractors"("watch_id") ON DELETE SET NULL,
  CONSTRAINT "mobilisation_signals_operator_id_fkey"
    FOREIGN KEY ("operator_id") REFERENCES "public"."employers"("employer_id") ON DELETE SET NULL,
  CONSTRAINT "mobilisation_signals_worksite_id_fkey"
    FOREIGN KEY ("worksite_id") REFERENCES "public"."worksites"("worksite_id") ON DELETE SET NULL,
  CONSTRAINT "mobilisation_signals_geofence_id_fkey"
    FOREIGN KEY ("geofence_id") REFERENCES "public"."geofences"("geofence_id") ON DELETE SET NULL,
  CONSTRAINT "mobilisation_signals_sector_id_fkey"
    FOREIGN KEY ("sector_id") REFERENCES "public"."sectors"("sector_id") ON DELETE SET NULL
);

COMMENT ON TABLE "public"."mobilisation_signals" IS
  'Unified early-warning stream. One row per event after cross-source dedup. AIS rows confirm timing; they are not the sole trigger.';

CREATE INDEX IF NOT EXISTS "idx_mobilisation_signals_occurred"
  ON "public"."mobilisation_signals" ("occurred_at" DESC);
CREATE INDEX IF NOT EXISTS "idx_mobilisation_signals_watch"
  ON "public"."mobilisation_signals" ("watch_contractor_id", "occurred_at" DESC);
CREATE INDEX IF NOT EXISTS "idx_mobilisation_signals_vessel"
  ON "public"."mobilisation_signals" ("vessel_id", "occurred_at" DESC);
CREATE INDEX IF NOT EXISTS "idx_mobilisation_signals_layer"
  ON "public"."mobilisation_signals" ("source_layer", "in_region");

CREATE TABLE IF NOT EXISTS "public"."mobilisation_alerts" (
  "alert_id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "rule_id" integer NOT NULL,
  "dedup_key" text NOT NULL,
  "status" text NOT NULL DEFAULT 'new',
  "priority" text NOT NULL,
  "title" text NOT NULL,
  "summary" text NOT NULL,
  "confidence" numeric(4,3) NOT NULL,
  "contractor_id" integer,
  "watch_contractor_id" integer,
  "vessel_id" integer,
  "operator_id" integer,
  "worksite_id" integer,
  "snoozed_until" timestamp with time zone,
  "status_note" text,
  "acknowledged_by" uuid,
  "acknowledged_at" timestamp with time zone,
  "dismissed_by" uuid,
  "dismissed_at" timestamp with time zone,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "mobilisation_alerts_dedup_unique" UNIQUE ("dedup_key"),
  CONSTRAINT "mobilisation_alerts_status_check" CHECK ("status" IN ('new', 'acknowledged', 'snoozed', 'dismissed')),
  CONSTRAINT "mobilisation_alerts_priority_check" CHECK ("priority" IN ('low', 'normal', 'high', 'critical')),
  CONSTRAINT "mobilisation_alerts_rule_id_fkey"
    FOREIGN KEY ("rule_id") REFERENCES "public"."mobilisation_rules"("rule_id"),
  CONSTRAINT "mobilisation_alerts_contractor_id_fkey"
    FOREIGN KEY ("contractor_id") REFERENCES "public"."employers"("employer_id") ON DELETE SET NULL,
  CONSTRAINT "mobilisation_alerts_watch_contractor_id_fkey"
    FOREIGN KEY ("watch_contractor_id") REFERENCES "public"."mobilisation_watch_contractors"("watch_id") ON DELETE SET NULL,
  CONSTRAINT "mobilisation_alerts_vessel_id_fkey"
    FOREIGN KEY ("vessel_id") REFERENCES "public"."vessels"("vessel_id") ON DELETE SET NULL,
  CONSTRAINT "mobilisation_alerts_operator_id_fkey"
    FOREIGN KEY ("operator_id") REFERENCES "public"."employers"("employer_id") ON DELETE SET NULL,
  CONSTRAINT "mobilisation_alerts_worksite_id_fkey"
    FOREIGN KEY ("worksite_id") REFERENCES "public"."worksites"("worksite_id") ON DELETE SET NULL
);

CREATE TABLE IF NOT EXISTS "public"."mobilisation_alert_signals" (
  "alert_id" bigint NOT NULL,
  "signal_id" bigint NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  PRIMARY KEY ("alert_id", "signal_id"),
  CONSTRAINT "mobilisation_alert_signals_alert_id_fkey"
    FOREIGN KEY ("alert_id") REFERENCES "public"."mobilisation_alerts"("alert_id") ON DELETE CASCADE,
  CONSTRAINT "mobilisation_alert_signals_signal_id_fkey"
    FOREIGN KEY ("signal_id") REFERENCES "public"."mobilisation_signals"("signal_id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "public"."mobilisation_alert_events" (
  "event_id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "alert_id" bigint NOT NULL,
  "actor_id" uuid,
  "action" text NOT NULL,
  "from_status" text,
  "to_status" text,
  "note" text,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "mobilisation_alert_events_alert_id_fkey"
    FOREIGN KEY ("alert_id") REFERENCES "public"."mobilisation_alerts"("alert_id") ON DELETE CASCADE
);

COMMENT ON TABLE "public"."mobilisation_alert_events" IS
  'Audit trail for acknowledge, snooze and dismiss. Written by trigger so the client cannot skip it.';

CREATE TABLE IF NOT EXISTS "public"."mobilisation_notifications" (
  "notification_id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "alert_id" bigint NOT NULL,
  "destination" text NOT NULL,
  "channel" text NOT NULL,
  "kind" text NOT NULL,
  "status" text NOT NULL DEFAULT 'pending',
  "error" text,
  "sent_at" timestamp with time zone,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "mobilisation_notifications_unique" UNIQUE ("alert_id", "destination", "channel", "kind"),
  CONSTRAINT "mobilisation_notifications_channel_check" CHECK (
    "channel" IN ('email', 'push', 'slack', 'teams')
  ),
  CONSTRAINT "mobilisation_notifications_status_check" CHECK (
    "status" IN ('pending', 'sent', 'failed', 'skipped')
  ),
  CONSTRAINT "mobilisation_notifications_alert_id_fkey"
    FOREIGN KEY ("alert_id") REFERENCES "public"."mobilisation_alerts"("alert_id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "public"."mobilisation_prefs" (
  "user_id" uuid PRIMARY KEY,
  "email_immediate" boolean NOT NULL DEFAULT true,
  "push_immediate" boolean NOT NULL DEFAULT false,
  "digest" text NOT NULL DEFAULT 'daily',
  "min_priority" text NOT NULL DEFAULT 'high',
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "mobilisation_prefs_digest_check" CHECK ("digest" IN ('off', 'daily', 'weekly')),
  CONSTRAINT "mobilisation_prefs_priority_check" CHECK ("min_priority" IN ('low', 'normal', 'high', 'critical')),
  CONSTRAINT "mobilisation_prefs_user_id_fkey"
    FOREIGN KEY ("user_id") REFERENCES "auth"."users"("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "public"."mobilisation_push_subscriptions" (
  "subscription_id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" uuid NOT NULL,
  "endpoint" text NOT NULL,
  "p256dh" text NOT NULL,
  "auth" text NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "mobilisation_push_subscriptions_endpoint_unique" UNIQUE ("endpoint"),
  CONSTRAINT "mobilisation_push_subscriptions_user_id_fkey"
    FOREIGN KEY ("user_id") REFERENCES "auth"."users"("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "public"."mobilisation_positions" (
  "position_id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "vessel_id" integer NOT NULL,
  "observed_at" timestamp with time zone NOT NULL,
  "latitude" numeric(9,6) NOT NULL,
  "longitude" numeric(9,6) NOT NULL,
  "sog_kn" numeric(6,2),
  "cog_deg" numeric(6,2),
  "destination" text,
  "eta" timestamp with time zone,
  "source" text NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "mobilisation_positions_unique" UNIQUE ("vessel_id", "observed_at", "source"),
  CONSTRAINT "mobilisation_positions_vessel_id_fkey"
    FOREIGN KEY ("vessel_id") REFERENCES "public"."vessels"("vessel_id") ON DELETE CASCADE
);

COMMENT ON TABLE "public"."mobilisation_positions" IS
  'Recent AIS fixes for internal alerting only. Do not expose this table publicly or republish coordinates. The poller deletes rows older than 14 days.';

CREATE TABLE IF NOT EXISTS "public"."mobilisation_settings" (
  "id" integer PRIMARY KEY DEFAULT 1,
  "slack_webhook_url" text,
  "teams_webhook_url" text,
  "ais_provider" text NOT NULL DEFAULT 'datalastic',
  "ais_satellite_enabled" boolean NOT NULL DEFAULT false,
  "escalation_window_days" integer NOT NULL DEFAULT 42,
  "contact_email" text,
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "mobilisation_settings_singleton" CHECK ("id" = 1),
  CONSTRAINT "mobilisation_settings_window_check" CHECK ("escalation_window_days" BETWEEN 7 AND 180)
);

INSERT INTO "public"."mobilisation_settings" ("id") VALUES (1) ON CONFLICT DO NOTHING;

-- Audit status changes, including snooze expiry performed by the service role.
CREATE OR REPLACE FUNCTION "public"."mobilisation_alert_audit"() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status OR NEW.snoozed_until IS DISTINCT FROM OLD.snoozed_until THEN
    INSERT INTO "public"."mobilisation_alert_events" (
      "alert_id", "actor_id", "action", "from_status", "to_status", "note"
    ) VALUES (
      NEW.alert_id,
      auth.uid(),
      CASE
        WHEN NEW.status = 'acknowledged' THEN 'acknowledged'
        WHEN NEW.status = 'snoozed' THEN 'snoozed'
        WHEN NEW.status = 'dismissed' THEN 'dismissed'
        WHEN OLD.status = 'snoozed' AND NEW.status = 'new' THEN 'unsnoozed'
        ELSE NEW.status
      END,
      OLD.status,
      NEW.status,
      NEW.status_note
    );
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS "trg_mobilisation_alert_audit" ON "public"."mobilisation_alerts";
CREATE TRIGGER "trg_mobilisation_alert_audit"
  AFTER UPDATE ON "public"."mobilisation_alerts"
  FOR EACH ROW EXECUTE FUNCTION "public"."mobilisation_alert_audit"();

DROP TRIGGER IF EXISTS "trg_vessels_updated_at" ON "public"."vessels";
CREATE TRIGGER "trg_vessels_updated_at" BEFORE UPDATE ON "public"."vessels"
  FOR EACH ROW EXECUTE FUNCTION "public"."update_updated_at"();
DROP TRIGGER IF EXISTS "trg_geofences_updated_at" ON "public"."geofences";
CREATE TRIGGER "trg_geofences_updated_at" BEFORE UPDATE ON "public"."geofences"
  FOR EACH ROW EXECUTE FUNCTION "public"."update_updated_at"();
DROP TRIGGER IF EXISTS "trg_mob_watch_contractors_updated_at" ON "public"."mobilisation_watch_contractors";
CREATE TRIGGER "trg_mob_watch_contractors_updated_at" BEFORE UPDATE ON "public"."mobilisation_watch_contractors"
  FOR EACH ROW EXECUTE FUNCTION "public"."update_updated_at"();
DROP TRIGGER IF EXISTS "trg_mob_rules_updated_at" ON "public"."mobilisation_rules";
CREATE TRIGGER "trg_mob_rules_updated_at" BEFORE UPDATE ON "public"."mobilisation_rules"
  FOR EACH ROW EXECUTE FUNCTION "public"."update_updated_at"();
DROP TRIGGER IF EXISTS "trg_mob_alerts_updated_at" ON "public"."mobilisation_alerts";
CREATE TRIGGER "trg_mob_alerts_updated_at" BEFORE UPDATE ON "public"."mobilisation_alerts"
  FOR EACH ROW EXECUTE FUNCTION "public"."update_updated_at"();
DROP TRIGGER IF EXISTS "trg_mob_prefs_updated_at" ON "public"."mobilisation_prefs";
CREATE TRIGGER "trg_mob_prefs_updated_at" BEFORE UPDATE ON "public"."mobilisation_prefs"
  FOR EACH ROW EXECUTE FUNCTION "public"."update_updated_at"();
DROP TRIGGER IF EXISTS "trg_mob_settings_updated_at" ON "public"."mobilisation_settings";
CREATE TRIGGER "trg_mob_settings_updated_at" BEFORE UPDATE ON "public"."mobilisation_settings"
  FOR EACH ROW EXECUTE FUNCTION "public"."update_updated_at"();

