-- Link watch rows to employers only on an exact name match, so a prefix
-- collision cannot attach the wrong company.
UPDATE "public"."mobilisation_watch_contractors" AS w
SET "employer_id" = e."employer_id"
FROM "public"."employers" AS e
WHERE w."employer_id" IS NULL
  AND e."is_active" = true
  AND lower(e."employer_name") = lower(w."canonical_name");

UPDATE "public"."vessels" AS v
SET "owner_operator_id" = e."employer_id"
FROM "public"."employers" AS e
WHERE v."owner_operator_id" IS NULL
  AND e."is_active" = true
  AND (
    lower(e."employer_name") = lower(v."owner_name")
    OR lower(coalesce(e."trading_name", '')) = lower(v."owner_name")
  );

UPDATE "public"."mobilisation_watch_contractors" AS w
SET "employer_id" = v."owner_operator_id"
FROM "public"."vessels" AS v
WHERE w."employer_id" IS NULL
  AND v."owner_operator_id" IS NOT NULL
  AND lower(v."owner_name") = lower(w."canonical_name");

