-- Grants and RLS. Staff (admin/user) maintain the watchlist. Every signed-in
-- user can read the feed. Viewers do not write. Service role bypasses RLS
-- for the pollers.

ALTER TABLE "public"."vessels" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."geofences" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."mobilisation_watch_contractors" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."mobilisation_watch_vessels" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."mobilisation_watch_keywords" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."mobilisation_sources" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."mobilisation_rules" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."mobilisation_signals" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."mobilisation_alerts" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."mobilisation_alert_signals" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."mobilisation_alert_events" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."mobilisation_notifications" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."mobilisation_prefs" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."mobilisation_push_subscriptions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."mobilisation_positions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."mobilisation_settings" ENABLE ROW LEVEL SECURITY;

DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'vessels', 'geofences', 'mobilisation_watch_contractors', 'mobilisation_watch_vessels',
    'mobilisation_watch_keywords', 'mobilisation_sources', 'mobilisation_rules',
    'mobilisation_signals', 'mobilisation_alerts', 'mobilisation_alert_signals',
    'mobilisation_alert_events', 'mobilisation_notifications', 'mobilisation_prefs',
    'mobilisation_push_subscriptions', 'mobilisation_positions', 'mobilisation_settings'
  ]
  LOOP
    EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC, anon', t);
    EXECUTE format('GRANT SELECT ON TABLE public.%I TO authenticated', t);
    EXECUTE format('GRANT ALL ON TABLE public.%I TO service_role', t);
  END LOOP;
END $$;

GRANT INSERT, UPDATE, DELETE ON TABLE "public"."vessels" TO "authenticated";
GRANT INSERT, UPDATE, DELETE ON TABLE "public"."geofences" TO "authenticated";
GRANT INSERT, UPDATE, DELETE ON TABLE "public"."mobilisation_watch_contractors" TO "authenticated";
GRANT INSERT, UPDATE, DELETE ON TABLE "public"."mobilisation_watch_vessels" TO "authenticated";
GRANT INSERT, UPDATE, DELETE ON TABLE "public"."mobilisation_watch_keywords" TO "authenticated";
GRANT UPDATE ON TABLE "public"."mobilisation_rules" TO "authenticated";
GRANT UPDATE ON TABLE "public"."mobilisation_alerts" TO "authenticated";
GRANT INSERT, UPDATE, DELETE ON TABLE "public"."mobilisation_prefs" TO "authenticated";
GRANT INSERT, UPDATE, DELETE ON TABLE "public"."mobilisation_push_subscriptions" TO "authenticated";
GRANT UPDATE ON TABLE "public"."mobilisation_settings" TO "authenticated";
GRANT UPDATE ON TABLE "public"."mobilisation_sources" TO "authenticated";

CREATE POLICY "mobilisation read vessels" ON "public"."vessels"
  FOR SELECT TO "authenticated" USING (true);
CREATE POLICY "mobilisation write vessels" ON "public"."vessels"
  FOR ALL TO "authenticated"
  USING ("public"."get_user_role"() = ANY (ARRAY['admin', 'user']))
  WITH CHECK ("public"."get_user_role"() = ANY (ARRAY['admin', 'user']));

