CREATE POLICY "mobilisation admin update settings" ON "public"."mobilisation_settings"
  FOR UPDATE TO "authenticated"
  USING ("public"."get_user_role"() = 'admin')
  WITH CHECK ("public"."get_user_role"() = 'admin');

DO $$
DECLARE
  seq text;
  spec text;
  tbl text;
  col text;
BEGIN
  FOREACH spec IN ARRAY ARRAY[
    'vessels.vessel_id',
    'geofences.geofence_id',
    'mobilisation_watch_contractors.watch_id',
    'mobilisation_watch_vessels.watch_vessel_id',
    'mobilisation_watch_keywords.keyword_id',
    'mobilisation_rules.rule_id',
    'mobilisation_signals.signal_id',
    'mobilisation_alerts.alert_id',
    'mobilisation_alert_events.event_id',
    'mobilisation_notifications.notification_id',
    'mobilisation_push_subscriptions.subscription_id',
    'mobilisation_positions.position_id'
  ]
  LOOP
    tbl := split_part(spec, '.', 1);
    col := split_part(spec, '.', 2);
    seq := pg_get_serial_sequence('public.' || tbl, col);
    IF seq IS NOT NULL THEN
      EXECUTE format('GRANT USAGE, SELECT ON SEQUENCE %s TO authenticated, service_role', seq);
    END IF;
  END LOOP;
END $$;
